onClick:
{{
  (async () => {
    await storeValue('selectedModus', 'Später'); 
    const jetzigerZeitstempel = moment().format('DD.MM.YYYY HH:mm');
    const activeV = String(appsmith.store.activeVentil || "").trim();
    const daten = Bewaesserung_Lesen.data || [];

    // 1. Unfertigen Eintrag suchen (0-basierter Array-Index)
    let existIndex = -1;

    for (let i = 0; i < daten.length; i++) {
      const row = daten[i];
      const vRow = String(row.Ventil || "").trim();
      const match = vRow === activeV || 
                    (!isNaN(parseFloat(vRow)) && parseFloat(vRow) === parseFloat(activeV));
      const unfertig = String(row.Status || "").trim().toLowerCase() !== "fertig";

      if (match && unfertig) {
        existIndex = i; // Array-Index für realRowIndex
        break;
      }
    }

    try {
      if (existIndex !== -1) {
        // --- FALL A: UNFERTIGER EINTRAG EXISTIERT -> ÜBERSCHREIBEN ---
        await Bewaesserung_Update_Eintrag.run({
          "realRowIndex": existIndex,
          "programm": appsmith.store.selectedProg,
          "modus": 'Später',
          "zeitstempel": jetzigerZeitstempel
        });
      } else {
        // --- FALL B: KEIN EINTRAG DA -> NEU ANLEGEN ---
        await Bewaesserung_Speichern.run({
          "ventilName": appsmith.store.activeVentil,
          "programm": appsmith.store.selectedProg,
          "modus": 'Später',
          "zeitstempel": jetzigerZeitstempel,
          "stammdaten": Stammdaten.data
        });
      }

      // 2. Stammdaten aktualisieren
      await Stammdaten_Update.run();

      // 3. Daten im Hintergrund neu laden
      await Promise.all([
        Bewaesserung_Lesen.run(),
        Stammdaten.run()
      ]);

      // 4. Modal schließen
      await closeModal('Modal_Programm');

    } catch (e) {
      showAlert("Fehler beim Speichern: " + e.message, "error");
    }
  })()
}}
